let conversion_rate = 1.0
let discount = 0.0
frappe.ui.form.on('Order Processing Request', {
    refresh: (frm, cdt, cdn) => {
      if(!frm.doc.sales_order) return;
      init(frm);
      if(!frappe.user_roles.includes("Accounts User")) {
          frm.set_df_property("s6", "hidden", true);
      }
      assignStockConsumptionSummary(frm, cdn);
      assignDeliveryNoteSummary(frm, cdn);
      frm.add_custom_button('Get Items from Sales Order', function() {
        assignQuantities(frm, cdn);    
      });
      frm.add_custom_button(__('Delivery Note'), function() {
            create_child(frm, "btb_cvs_support.api.opr.get_mapped_delivery_note")
        }, 'Create');
      frm.add_custom_button(__('Stock Consumption'), function() {
            create_child(frm, "btb_cvs_support.api.opr.get_mapped_stock_consumption")
        }, 'Create');

    },
    sales_order:(frm, cdt, cdn) => {
        console.log(frm.doc.sales_order);
        assignQuantities(frm, cdn);
    }

});

function create_child(frm, method) {
    frappe.model.open_mapped_doc({
        method: method,
        frm: frm
    });
}

frappe.ui.form.on("Accessories", {
    quantity: (frm, cdt, cdn)  => {
        updateAmount(frm, cdt, cdn, "Accessories");
    }
});

frappe.ui.form.on('Quantities Table', {
    refresh: (frm, cdt, cdn) => {
        updateFittingSqm(frm, cdt, cdn);
        updateFittingNos(frm, cdt, cdn);
    },
    straight_sqm: (frm, cdt, cdn) => {
        updateFittingSqm(frm, cdt, cdn);
    },
    quantity: (frm, cdt, cdn) => {
        updateFittingSqm(frm, cdt, cdn);
        updateAmount(frm, cdt, cdn, "quantities_required");
    },
    straight_no: (frm, cdt, cdn) => {
        updateFittingNos(frm, cdt, cdn);
    },
    total_nos: (frm, cdt, cdn) => {
        updateFittingNos(frm, cdt, cdn);
    }
});

function updateAmount(frm, cdt, cdn, refreshField) {
    let item = locals[cdt][cdn];
    frappe.model.set_value(cdt, cdn, "amount", item.rate * item.quantity);
    frm.refresh_field(refreshField);
    set_total_approx_value(frm);
}
function init(frm) {
    frappe.call({
        type: "GET",
        method: "btb_cvs_support.api.opr.get_sales_order_details",
        args: {
            "sales_order_number": frm.doc.sales_order
        },
        callback: function (result) {
            let item = result.message;
            conversion_rate = item.conversion_rate;
            discount = item.additional_discount_percentage / 100.0;
            set_total_approx_value(frm);
        }
    });
}

function set_total_approx_value(frm) {
        var total_approx_value = 0;
        $.each(frm.doc.quantities_required || [], function(i, d) {
               total_approx_value += flt(d.amount);
        });
         $.each(frm.doc.accessories || [], function(i, d) {
               total_approx_value += flt(d.amount);
        });
        total_approx_value = (1 - discount) * total_approx_value * conversion_rate;
        if(frm.doc.approx_value_ == total_approx_value) return;
        frm.set_value("approx_value_", total_approx_value);
}

function updateFittingSqm(frm, cdt, cdn) {
    let result = getDifference(locals[cdt][cdn], "quantity", "straight_sqm");
    if(result === null) return;
    frappe.model.set_value(cdt, cdn, "fitting_sqm", result);
    frm.refresh_field("quantities_required");
}

function updateFittingNos(frm, cdt, cdn) {
    let result = getDifference(locals[cdt][cdn], "total_nos", "straight_no");
    if(result === null) return;
    frappe.model.set_value(cdt, cdn, "fitting_no", result);
    frm.refresh_field("quantities_required");
}

function getDifference(item, p1, p2) {
    if (item.uom.toLowerCase() != "sqm") return null;
    //if(isNaN(item[p1]) || isNaN(item[p2])) return null;
    return (item[p1] ?? 0) - (item[p2] ?? 0);
}

function assignQuantities(frm, cdn) {
    frappe.call({
        type: "GET",
        method: "btb_cvs_support.api.opr.get_pending_quantities",
        args: {
            "sales_order_number": frm.doc.sales_order,
            "opr_name": cdn
        },
        callback: function (result) {
            let items = result.message;
            for (var i = 0; i < items.length; i++) {
                if (items[i].custom_manufactured_item) addQuantity(frm, items[i]);
                else addAccessory(frm, items[i]);
            }
            frm.refresh_field("quantities_required");
            frm.refresh_field("accessories");
            set_total_approx_value(frm);
        }
    })
}

function addQuantity(frm, item) {
    let child = getItem(frm.doc.quantities_required, "so_detail", item.so_detail);
    if (child !== null) return;
    child = {
        so_detail: item.so_detail, item_code: item.item_code, description: item.description, 
        quantity: item.quantity, rate: item.rate, amount: item.rate * item.quantity,
        so: frm.doc.sales_order, uom: item.uom
    };
    if(item.uom.toLowerCase() === "sqm") {
        child.fitting_sqm = item.quantity;
    }
    frm.add_child("quantities_required", child);

}

function addAccessory(frm, item) {
    let child = getItem(frm.doc.accessories, "item", item.item_code);
    if (child !== null) return;
    child = {
        so_detail: item.so_detail, item: item.item_code, description: item.description, 
        quantity: item.quantity, rate: item.rate, amount: item.rate * item.quantity, 
        uom: item.uom
    };
    frm.add_child("accessories", child);

}

function getItem(items, property, value) {
    let result = items.filter(item => item[property] === value);
    if (result.length === 0) return null;
    return result[0];
}

function assignStockConsumptionSummary(frm, cdn) {
    frappe.call({
        type: "GET",
        method: "btb_cvs_support.api.opr.get_stock_consumption_summary",
        args: {
            "opr_name": cdn
        },
        callback: function (result) {
            frm.set_df_property("stock_consumption_html", "options", result.message);
        }
    });
}

function assignDeliveryNoteSummary(frm, cdn) {
    frappe.call({
        type: "GET",
        method: "btb_cvs_support.api.opr.get_delivery_note_summary",
        args: {
            "opr_name": cdn
        },
        callback: function (result) {
            frm.set_df_property("delivery_note_html", "options", result.message);
        }
    });
}
